def compute(vars):
    fees = [
        vars["v1"],
        vars["v2"],
        vars["v3"],
        vars["v4"],
        vars["v5"],
        vars["v6"],
    ]
    total_fees = sum(fees)
    count = len(fees)
    if count == 0:
        return None
    average_fee = total_fees / count
    return {
        "value": average_fee,
        "trace": {
            "total_fees": total_fees,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None,
            },
        },
    }
